use std::collections::{BTreeMap,BTreeSet}; use serde::{Deserialize,Serialize}; use super::{error::{AdmissionError,AdmissionErrorKind,Result},receipt::{Receipt,ReceiptChain},subject::SubjectId};
#[derive(Clone,Debug,Default,Serialize,Deserialize)] pub struct Ledger{chains:BTreeMap<String,ReceiptChain>,seen:BTreeSet<String>}
impl Ledger{pub fn append(&mut self,r:Receipt)->Result<()>{if self.seen.contains(&r.id){return Err(AdmissionError::new(AdmissionErrorKind::Conflict,"ledger.duplicate","receipt already present").subject(r.subject.key()))}let k=r.subject.key();self.chains.entry(k).or_default().append(r.clone())?;self.seen.insert(r.id);Ok(())}pub fn chain(&self,s:&SubjectId)->Option<&ReceiptChain>{self.chains.get(&s.key())}pub fn verify(&self)->Result<()>{for c in self.chains.values(){c.verify()?}Ok(())}pub fn len(&self)->usize{self.seen.len()}pub fn is_empty(&self)->bool{self.seen.is_empty()}}